-- P0: scope residual merchant records and retain trusted global administration.
ALTER TABLE public."audit_events" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
DROP POLICY IF EXISTS "audit_events_privacy_boundary" ON public."audit_events";
--> statement-breakpoint
CREATE POLICY "audit_events_privacy_boundary" ON public."audit_events" AS PERMISSIVE FOR ALL TO public USING ((CASE WHEN (has_function_privilege(session_user, 'public.fawri_authentication_runtime()', 'EXECUTE') AND EXISTS (SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname = session_user AND r.rolcanlogin AND NOT (r.rolsuper OR r.rolbypassrls OR r.rolcreaterole))) THEN true WHEN has_function_privilege(session_user, 'public.fawri_issue_admin_directory_audit(text,text,text)', 'EXECUTE') THEN false ELSE public.fawri_tenant_or_audited_admin("audit_events"."merchant_id") END)) WITH CHECK ((CASE WHEN (has_function_privilege(session_user, 'public.fawri_authentication_runtime()', 'EXECUTE') AND EXISTS (SELECT 1 FROM pg_catalog.pg_roles r WHERE r.rolname = session_user AND r.rolcanlogin AND NOT (r.rolsuper OR r.rolbypassrls OR r.rolcreaterole))) THEN true WHEN has_function_privilege(session_user, 'public.fawri_issue_admin_directory_audit(text,text,text)', 'EXECUTE') THEN false ELSE public.fawri_tenant_or_audited_admin("audit_events"."merchant_id") END));
--> statement-breakpoint
